data.setupCode:
// A small canvas for the clock overlay (white text, the shader tints and places it)
state.c = canvas(512, 160);
state.g = state.c.getContext('2d');
state.ff = 0;            // extra hours added by "Time speed" (fast-forward)
state.label = '';

data.code:
// The real time of day drives the sky. Date() gives the local time; "Time speed"
// fast-forwards (1 = real time, 3600 = one hour per second) and "Hour offset" shifts it.
const speed = params['Time speed'] ?? 1;
state.ff += dt * (speed - 1) / 3600;                    // hours gained by fast-forwarding
const now = new Date();
const realH = now.getHours() + now.getMinutes() / 60 + now.getSeconds() / 3600 + now.getMilliseconds() / 3.6e6;
const total = realH + (params['Hour offset'] ?? 0) + state.ff;   // hours since today's midnight
const hour = ((total % 24) + 24) % 24;
const dayShift = Math.floor(total / 24);
const start = new Date(now.getFullYear(), 0, 0);
const doy = (now - start) / 864e5 + dayShift;                     // day of the year

// Sun: declination over the year, hour angle over the day (solar time ~ clock time)
const rad = Math.PI / 180;
const lat = (params['Latitude'] ?? 48) * rad;
const dec = -23.44 * rad * Math.cos(2 * Math.PI * (doy + 10) / 365);
const H = (hour - 12) / 24 * 2 * Math.PI;
// local frame: x = east, y = up, z = north (the camera looks south, -z)
const dir = (d, h) => [
  -Math.cos(d) * Math.sin(h),
  Math.sin(lat) * Math.sin(d) + Math.cos(lat) * Math.cos(d) * Math.cos(h),
  Math.cos(lat) * Math.sin(d) - Math.sin(lat) * Math.cos(d) * Math.cos(h),
];
const sun = dir(dec, H);

// Moon: phase from a known new moon (2000-01-06 18:14 UTC), synodic month 29.53 days;
// it trails the sun by phase x 24 h (a rough but pretty approximation)
const days = (now.getTime() - Date.UTC(2000, 0, 6, 18, 14)) / 864e5 + (params['Hour offset'] ?? 0) / 24 + state.ff / 24;
const phase = ((days / 29.530588) % 1 + 1) % 1;                 // 0 new, 0.5 full
const moonDec = -23.44 * rad * Math.cos(2 * Math.PI * (doy + 10 + phase * 182.6) / 365);
const moon = dir(moonDec, H - phase * 2 * Math.PI);

// Clock overlay, redrawn only when the minute changes
const hh = Math.floor(hour), mm = Math.floor((hour - hh) * 60);
const label = `${String(hh).padStart(2, '0')}:${String(mm).padStart(2, '0')}`;
if (label !== state.label) {
  state.label = label;
  const g = state.g;
  g.clearRect(0, 0, 512, 160);
  g.fillStyle = '#000';
  g.fillRect(0, 0, 512, 160);
  g.fillStyle = '#fff';
  g.textBaseline = 'middle';
  g.font = '600 104px "Helvetica Neue", Arial, sans-serif';
  g.fillText(label, 16, 70);
  g.font = '500 26px "Helvetica Neue", Arial, sans-serif';
  const names = ['new moon', 'waxing crescent', 'first quarter', 'waxing gibbous', 'full moon', 'waning gibbous', 'last quarter', 'waning crescent'];
  g.globalAlpha = 0.75;
  g.fillText(`${speed > 1.01 ? `×${Math.round(speed)}  ·  ` : ''}${names[Math.round(phase * 8) % 8]}`, 20, 140);
  g.globalAlpha = 1;
}
// Stars turn with the sky around the celestial pole
const pole = [0, Math.sin(lat), Math.cos(lat)];
return {
  sunDir: vec3(sun), moonDir: vec3(moon), moonPhase: float(phase),
  pole: vec3(pole), starTurn: float(H), clock: state.c, hour: float(hour),
};

ClockSky.customGLSL:
// @node clockSky
// @title Clock Sky
// @category custom
// @description A sky for any time of day, looking south over hills: day / night gradient, golden and blue hour toward the sun, sun disc and halo, a phased moon with craters, stars turning around the celestial pole (pole, starTurn), drifting clouds lit by sun, dusk or moon, hills with town lights at night, and a clock overlay (clockTex, a canvas). Directions come from the JS node (x = east, y = up, z = north). Returns HDR color.
float cs_hash(vec2 p) {
    p = fract(p * vec2(123.34, 456.21));
    p += dot(p, p + 45.32);
    return fract(p.x * p.y);
}

float cs_noise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    return mix(mix(cs_hash(i), cs_hash(i + vec2(1.0, 0.0)), f.x), mix(cs_hash(i + vec2(0.0, 1.0)), cs_hash(i + vec2(1.0, 1.0)), f.x), f.y);
}

float cs_fbm(vec2 p) {
    float s = 0.0;
    float a = 0.5;
    for (int i = 0; i < 5; i++) {
        s += a * cs_noise(p);
        p = p * 2.03 + 17.1;
        a *= 0.5;
    }
    return s;
}

vec3 cs_rotate(vec3 v, vec3 k, float a) {
    return v * cos(a) + cross(k, v) * sin(a) + k * dot(k, v) * (1.0 - cos(a));
}

vec3 clockSky(vec2 uv, vec3 sunDir, vec3 moonDir, float moonPhase, vec3 pole, float starTurn, sampler2D clockTex, float clouds, float stars, float showClock) {
    float aspect = u_resolution.x / max(u_resolution.y, 1.0);
    vec2 p = (uv - 0.5) * vec2(aspect, 1.0);
    vec3 rd = normalize(vec3(-p.x * 1.1, p.y * 1.1 + 0.2, -1.0));   // facing south: screen right = west (-x)
    vec3 sun = normalize(sunDir);
    vec3 moon = normalize(moonDir);
    float sAlt = sun.y;
    float day = smoothstep(-0.1, 0.22, sAlt);
    float twilight = exp(-abs(sAlt + 0.03) * 8.0);
    float night = 1.0 - smoothstep(-0.16, 0.0, sAlt);
    float h = max(rd.y, 0.0);

    // Sky gradient
    vec3 zen = mix(vec3(0.004, 0.008, 0.026), vec3(0.14, 0.34, 0.8), day);
    vec3 hor = mix(vec3(0.02, 0.035, 0.08), vec3(0.6, 0.76, 0.97), day);
    vec3 sky = mix(hor, zen, pow(h, 0.45));
    float toward = max(dot(normalize(rd.xz + 1e-5), normalize(sun.xz + 1e-5)), 0.0);
    vec3 dusk = mix(vec3(1.0, 0.36, 0.1), vec3(0.95, 0.5, 0.6), smoothstep(0.0, 0.4, h));
    sky = mix(sky, dusk, twilight * exp(-h * 3.5) * (0.3 + 0.7 * pow(toward, 3.0)));
    sky += vec3(0.28, 0.12, 0.4) * twilight * exp(-h * 1.5) * 0.18;

    // Stars, turning around the celestial pole
    if (night > 0.0 && rd.y > -0.05) {
        vec3 q = cs_rotate(rd, normalize(pole), -starTurn);
        vec2 sp = vec2(atan(q.z, q.x), asin(clamp(q.y, -1.0, 1.0))) * 70.0;
        vec2 cell = floor(sp);
        vec2 f = fract(sp) - 0.5;
        float rnd = cs_hash(cell);
        vec2 off = vec2(cs_hash(cell + 3.1), cs_hash(cell + 7.7)) - 0.5;
        float star = smoothstep(0.08, 0.0, length(f - off * 0.6)) * step(0.82, rnd);
        float tw = 0.65 + 0.35 * sin(u_time * (2.0 + rnd * 4.0) + rnd * 40.0);
        sky += vec3(0.85, 0.9, 1.0) * star * tw * pow(rnd, 6.0) * 2.5 * night * stars * smoothstep(0.0, 0.15, rd.y);
    }

    // Sun: halo and disc
    float cs = dot(rd, sun);
    float up = smoothstep(-0.06, 0.02, sAlt);
    sky += mix(vec3(1.0, 0.5, 0.2), vec3(1.0, 0.9, 0.7), day) * (pow(max(cs, 0.0), 10.0) * 0.45 + pow(max(cs, 0.0), 300.0) * 0.8) * smoothstep(-0.2, 0.0, sAlt);
    sky += vec3(1.0, 0.95, 0.85) * smoothstep(0.99985, 0.99992, cs) * 12.0 * up;

    // Moon with its phase (0 new, 0.5 full; waxing = lit on the right) and craters
    float cm = dot(rd, moon);
    float mR = 0.035;
    if (cm > cos(mR * 1.6)) {
        vec3 mr = normalize(cross(moon, vec3(0.0, 1.0, 0.0)));
        vec3 mu = cross(mr, moon);
        vec3 dv = rd - moon * cm;
        vec2 q = vec2(dot(dv, -mr), dot(dv, mu)) / sin(mR);
        float r2 = dot(q, q);
        float ang = moonPhase * 6.2831853;
        vec3 ld = vec3(sin(ang), 0.0, -cos(ang));
        vec3 nrm = vec3(q, sqrt(max(1.0 - r2, 0.0)));
        float lit = smoothstep(-0.04, 0.08, dot(nrm, ld));
        float crater = 0.72 + 0.28 * cs_fbm(q * 3.0 + 5.0);
        vec3 mcol = vec3(0.98, 0.95, 0.86) * crater * lit * 1.4 + vec3(0.025, 0.03, 0.05);
        float disc = 1.0 - smoothstep(0.92, 1.0, r2);
        sky = mix(sky, mcol, disc * (1.0 - 0.75 * day) * smoothstep(-0.02, 0.02, moon.y));
    }
    float lunar = 0.5 - 0.5 * cos(moonPhase * 6.2831853);
    sky += vec3(0.5, 0.6, 0.85) * pow(max(cm, 0.0), 300.0) * 0.6 * lunar * (1.0 - day) * smoothstep(-0.02, 0.05, moon.y);

    // Clouds on a plane above
    if (rd.y > 0.0 && clouds > 0.0) {
        vec2 cp = rd.xz / (rd.y + 0.12) * 0.5 + vec2(u_time * 0.006, u_time * 0.002);
        float c = cs_fbm(cp * 2.0);
        float th = 0.78 - clouds * 0.5;
        float cov = smoothstep(th, th + 0.25, c) * smoothstep(0.0, 0.18, rd.y);
        vec3 moonLit = vec3(0.07, 0.08, 0.12) * (0.4 + 0.8 * lunar * smoothstep(0.0, 0.2, moon.y));
        vec3 cc = mix(moonLit, vec3(0.92, 0.94, 1.0) * (0.75 + 0.25 * sAlt), day);
        cc = mix(cc, vec3(1.0, 0.55, 0.4), twilight * (0.5 + 0.5 * toward) * 0.8);
        cc *= 0.8 + 0.2 * smoothstep(th, th + 0.4, c);
        sky = mix(sky, cc, cov * 0.92);
    }

    // Hills (screen space): a far ridge and a near ridge, town lights at night
    float hy = -0.2 / 1.1;                              // horizon height in p
    float far = hy + 0.035 + 0.06 * cs_fbm(vec2(p.x * 2.2 + 11.0, 1.0));
    float nearR = hy - 0.05 + 0.09 * cs_fbm(vec2(p.x * 1.3 + 3.0, 5.0));
    vec3 amb = mix(hor, zen, 0.3);
    vec3 col = sky;
    col = mix(col, amb * 0.45 + dusk * twilight * 0.06, smoothstep(far + 0.002, far - 0.002, p.y));
    if (p.y < nearR + 0.003) {
        vec3 ground = amb * 0.18;
        float depth = clamp((nearR - p.y) * 4.0, 0.0, 1.0);
        vec2 lc = floor(vec2(p.x * 90.0, p.y * 90.0));
        float lr = cs_hash(lc + 1.3);
        vec2 lf = fract(vec2(p.x * 90.0, p.y * 90.0)) - 0.5;
        float town = smoothstep(0.55, 0.7, cs_noise(vec2(p.x * 5.0 + 2.0, 0.5)));          // a few villages
        float band = smoothstep(0.02, 0.08, depth) * (1.0 - smoothstep(0.25, 0.45, depth)); // along the valley
        float lamp = step(0.88, lr) * smoothstep(0.25, 0.0, length(lf)) * town * band * (0.7 + 0.3 * sin(u_time * 3.0 + lr * 50.0));
        ground += vec3(1.0, 0.7, 0.35) * lamp * 1.5 * night;
        col = mix(col, ground, smoothstep(nearR + 0.002, nearR - 0.002, p.y));
    }

    // Clock overlay (bottom left)
    vec2 cq = vec2((uv.x - 0.06) / 0.26, (uv.y - 0.07) / (0.26 * 0.3125 * aspect));
    if (cq.x > 0.0 && cq.x < 1.0 && cq.y > 0.0 && cq.y < 1.0) {
        float t = texture(clockTex, cq).r;
        col = mix(col, vec3(1.0, 0.97, 0.92) * 1.8, t * showClock * 0.9);
    }
    return col;
}
